WITH lines AS (SELECT id, plan, effective_from, EXPLODE_OUTER(tier_prices) AS tier_value FROM price_tiers) SELECT *, SUM(tier_value) OVER (PARTITION BY MONTH(effective_from), plan) AS effective_from_month_sum_tier_value, RANK() OVER (ORDER BY tier_value DESC NULLS FIRST) AS tier_value_rank, MAX(tier_value) OVER (PARTITION BY plan) AS plan_max_tier_value, MIN(tier_value) OVER (PARTITION BY plan) AS plan_min_tier_value FROM lines WHERE tier_value < 53
